#!/usr/bin/env python3
"""Write a review report from recorded results; contains no GT text or pixels."""
import json,pathlib
B=pathlib.Path('/data/coding/scanweave/work/books01'); P=pathlib.Path(__file__).resolve().parents[1]
lock=json.loads((P/'sources.lock.json').read_text()); costs=json.loads((P/'provenance/phase0-costs.json').read_text()); gt=json.loads((P/'provenance/gt-summary.json').read_text()); r=json.loads((B/'registration.json').read_text())
def f(v,n=2):return '—' if v is None else f'{v:.{n}f}'
s=['# BOOKS-01 Phase 0 preparation','', '**Status: selection frozen with material open issues below.** This is not a Phase 1 comparison.','', 'Quiver revisions are in `phase0/repo-pins.json`; FineBooks dataset and image revisions, source URLs and byte hashes are in the provenance and lock files. Twelve IA original-capture JP2 codestreams use irreversible 9/7 wavelets and decode to RGB8 via the pinned Pillow/OpenJPEG versions. Their candidates were fetched as individual tar members. All 12 use WebP, labelled lossy-origin and processed-derivative: original camera frames differ from rotated, cropped, deskewed and tone-processed access derivatives, outside the approved geometry. The patch matcher search window was not the deciding factor. Holdout files were hashed as bytes only. The accepted split is book-disjoint and unchanged.','', 'The language rule is `deu_latf` for Quiver Fraktur, `deu_latf+lat` for fontmix, `lat` for Alberti Antiqua, and `deu` for the other Antiqua work; FineBooks uses the volume language string in the accepted proposal. Each string is recorded per dev page.','', 'Each dev PDF embeds decoded RGB8 samples using Flate at the recorded physical DPI. The builder compares the decompressed embedded samples byte-for-byte and checks a second build for identical PDF bytes. The same deterministic check is applied to the 15 per-work PDFs. GT and alignment overlays are local under the designated work directory.','', '## FineBooks registration','', 'Patch matching uses 128-pixel access-image patches and searches each exact quarter-turn around the scandata crop; the accepted rule is in `phase0/REGISTRATION.md`. Residual is p95 among inliers, in JP2 pixels; the fraction is the proportion of qualifying matches within 2 px. A dash means not measurable, not zero. Where available, the scale and translation in the source lock apply to the rotated JP2 frame.','', '| Page | Residual px | Inliers / patches | Inlier fraction | Ink delta | Decision |','|---|---:|---:|---:|---:|---|']
for k,v in r.items():s.append(f"| {k} | {f(v.get('residual_p95_px'))} | {v.get('inliers',0)} / {v.get('patches',0)} | {f(v.get('inlier_fraction'))} | {f(v.get('ink_containment_delta'))} | webp: camera frame vs processed-derivative geometry |")
s+=['','## Quiver DPI evidence','','Physical sizes are implied by the TIFF tags, in millimetres. Confidence is moderate when METS includes a format and low when it supplies no physical format or dimensions. TIFF values are used provisionally in the latter case; they have not been independently confirmed.','', '| Page | DPI | Implied size mm | METS extent | Confidence |','|---|---:|---:|---|---|']
for k,v in lock['pages'].items():
 if not k.startswith('quiver/'):continue
 d=v['dpi_evidence']; ex='; '.join(d['mets_extents']); s.append(f"| {k} | {v['resolved_dpi']:g} | {d['implied_size_mm'][0]:g} × {d['implied_size_mm'][1]:g} | {ex.replace('|','/')} | {d['confidence']} |")
s+=['','## Smoke and costs','','The first smoke attempt failed because the prepared model directory omitted Tesseract’s `hocr` configuration. The system Tesseract 5.3.4 configuration was copied locally (hash in costs), and the same page was retried. The completed report records `native_source_samples`; no comparison was run.','',f"Logical disk bytes: {costs['disk_bytes_logical_by_category']}. Saved source file bytes: {costs['unique_source_file_bytes']:,}. PDF/GT build wall time: {costs['wall_seconds']['source_pdf_gt_build']:.1f} s. The original fetch, registration and smoke elapsed times and actual network bytes were not captured; they are explicitly null in the cost record.",'','## Open issues','', '- All 12 FineBooks XML files contain TextRegion polygons and text but no TextLine elements. Line counts are zero, region text is preserved without inventing line boxes, and line-polygon ink containment cannot be measured. The accepted rule therefore forces fallback even when the patch correlation alone might pass. Line-level alignment metrics for these pages require a separately approved methodology or different GT.','- For Quiver works whose METS gives no physical format or dimensions, the TIFF DPI is provisional and low confidence. A catalogue-based physical-size check remains needed before treating those page sizes as established.','- Fetch, registration and smoke timing and actual network byte totals were not instrumented; the missing measurements cannot be reconstructed reliably.','- The camera-frame versus processed-derivative geometry is outside the approved registration model; correlation is supporting evidence, not the fallback decision basis.','']
(P/'PHASE0.md').write_text('\n'.join(s))
